import classNames from 'classnames'
import {memo, useMemo} from 'react'

import {nth} from '../../../../utils/printCount'
import pagerWarning from '../PagerWarning/PagerWarning.container'
import styles from '../PagerWarning/PagerWarning.module.css'
import type {Props} from '../PagerWarning/PagerWarning.types'

function TestHistoryPagerWarning({className, currentPage, total, isLoading, show}: Props) {
  const content = useMemo(() => {
    if (total === 0 && currentPage !== 1) {
      return `There are no test runs on requested ${nth(
        currentPage,
      )} page. Try going to an earlier page.`
    }

    if (total === 0 && isLoading !== true) {
      return `No test runs found`
    }

    return null
  }, [currentPage, total, isLoading])
  return show && content != null ? (
    <div className={classNames(className, styles.warning)}>{content}</div>
  ) : null
}

export default pagerWarning(memo(TestHistoryPagerWarning))
