import {mapProps, withProps} from 'recompose'

import compose from 'lodash/flowRight'
import {connect} from 'react-redux'
import type {EntryPointProps} from 'react-relay'
import {useParams} from 'react-router'

import withHook from '../../../hocs/withHook'
import {withBranchProps} from '../../../hooks/routes'
import type {State} from '../../../reducers/types'
import {withLocation} from '../../../routes'
import {getBuildType, getProject} from '../../../selectors'
import {toBuildTypeId, toProjectId, toTestId} from '../../../types'
import {queryToObject} from '../../../utils/queryParams'
import type {BranchSelectBranchesQuery} from '../../common/BranchSelect/__generated__/BranchSelectBranchesQuery.graphql'

import TestHistoryPage from './TestHistoryPage'
import {TestPageTabNamesEnum} from './TestHistoryPage.tabs'
import type {OwnProps, StateProps, ComposeProps} from './TestHistoryPage.types'

const mapStateToProps = (
  state: State,
  {projectId, buildTypeId}: OwnProps & ComposeProps,
): StateProps => {
  const {internalId: projectInternalId, name: projectName} = getProject(state, projectId) ?? {}
  const {name: buildTypeName} = getBuildType(state, buildTypeId) ?? {}
  return {
    projectInternalId,
    projectName,
    buildTypeName,
  }
}

const TestHistoryPageContainer = compose(
  withHook(useParams),
  withLocation,
  withBranchProps,
  withProps(({location}) => {
    const defaultTab = TestPageTabNamesEnum.OVERVIEW
    const query = queryToObject(location?.search)
    return {
      currentTab: query.testTab ?? defaultTab,
      projectId: query.currentProjectId,
      pipelineId: query.currentPipelineId,
      buildTypeId: query.currentBuildTypeId,
    }
  }),
  mapProps(
    ({
      testId,
      projectId,
      buildTypeId,
      pipelineId,
      currentTab,
      ...restProps
    }: OwnProps & ComposeProps) => ({
      testId: toTestId(testId),
      projectId: projectId != null ? toProjectId(projectId) : null,
      buildTypeId: buildTypeId != null ? toBuildTypeId(buildTypeId) : null,
      pipelineId,
      currentTab: currentTab != null ? currentTab : null,
      ...restProps,
    }),
  ),
  connect(mapStateToProps),
)(TestHistoryPage)

type Queries = {branches: BranchSelectBranchesQuery}
export default function TestHistoryPageOuterContainer({
  queries,
  props,
}: EntryPointProps<Queries, {}, OwnProps, {}>) {
  return <TestHistoryPageContainer {...props} branchesQueryRef={queries.branches} />
}
export type TestHistoryPageOuterContainerComponent = typeof TestHistoryPageOuterContainer
