import type {ComponentEnhancer} from 'recompose'
import {withProps, withHandlers, branch as branchHOC} from 'recompose'

import compose from 'lodash/flowRight'
import type {ConnectedProps} from 'react-redux'
import {connect} from 'react-redux'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import type {BranchSelectBranchesQuery} from '../components/common/BranchSelect/__generated__/BranchSelectBranchesQuery.graphql'
import BranchSelect from '../components/common/BranchSelect/BranchSelect.container'
import {
  isForbiddenCombo,
  Modes,
} from '../components/pages/BuildTypePage/BuildTypeOverviewTab/BuildTypeOverviewTab.modes'
import withEffect from '../hocs/withEffect'
import withHook from '../hocs/withHook'
import type {BranchProps} from '../hooks/routes'
import {useProjectOrBuildTypeNode, withBranchProps} from '../hooks/routes'
import type {State} from '../reducers/types'
import type {LocationProps} from '../routes'
import {getHrefWithQueryParams, withLocation} from '../routes'
import {getProjectId} from '../selectors'
import type {Branch} from '../services/rest'
import type {ProjectOrBuildTypeNode} from '../types'
import {BS} from '../types/BS_types'
import {parseBranch, stringifyBranch} from '../utils/branchNames'

import type {Policy} from 'src/rest/branches'

type OwnProps = {
  className?: string
  projectOrBuildTypeNode?: ProjectOrBuildTypeNode | null | undefined
  policy: Policy
  onSelect?: (selected: Branch | null | undefined, replace?: boolean) => unknown
  branchesQueryRef: PreloadedQuery<BranchSelectBranchesQuery>
}

const connector = connect((state: State, {projectOrBuildTypeNode}: OwnProps) => ({
  projectId: getProjectId(state, projectOrBuildTypeNode),
}))
type ReduxProps = ConnectedProps<typeof connector>

export default compose(
  withLocation,
  withBranchProps,
  branchHOC(
    (props: OwnProps) => props.projectOrBuildTypeNode == null,
    withHook(() => ({
      projectOrBuildTypeNode: useProjectOrBuildTypeNode(),
    })) as ComponentEnhancer<OwnProps, OwnProps>,
  ),
  connector,
  withProps(({branch}: OwnProps & BranchProps) => ({
    selected: branch,
  })),
  withEffect(
    (props: LocationProps & BranchProps & ReduxProps) => props.branch,
    props => props.projectId,
    props => props.location,
    props => props.navigate,
    (branch, projectId, location, navigate) => {
      if (branch != null || projectId == null) {
        return
      }

      const savedBranch = BS?.Branch?.getBranch(projectId)

      if (savedBranch != null) {
        navigate(
          getHrefWithQueryParams(location, null, ({mode, ...rest}) => ({
            ...rest,
            branch: savedBranch,
            mode: isForbiddenCombo(parseBranch(savedBranch), mode) ? Modes.BUILDS : mode,
          })),
          {
            replace: true,
            preventScrollReset: true,
          },
        )
      }
    },
  ),
  withHandlers({
    onSelect:
      ({navigate, location, projectId, onSelect}: OwnProps & LocationProps & ReduxProps) =>
      (selected: Branch | null | undefined, replace?: boolean) => {
        if (onSelect != null) {
          onSelect(selected, replace)
        } else {
          const branch = stringifyBranch(selected)

          if (projectId != null && BS?.Branch) {
            BS.Branch.saveBranch(projectId, branch)
          }

          navigate(
            getHrefWithQueryParams(location, null, ({mode, ...rest}) => ({
              ...rest,
              branch,
              mode: isForbiddenCombo(selected, mode) ? Modes.BUILDS : mode,
            })),
            {
              replace,
              preventScrollReset: true,
            },
          )
        }
      },
  }),
)(BranchSelect)
