import {Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import {HTTPError, HTTPCodesEnum} from '@jetbrains/teamcity-ui/dist/services'
import type {FetchBaseQueryError} from '@reduxjs/toolkit/query'
import {memo, Suspense, useCallback, useEffect, useMemo} from 'react'
import {useLocation, useNavigate} from 'react-router'

import BranchFilter from '../../../containers/BranchFilter'
import {useAppSelector} from '../../../hooks/react-redux'
import useDocumentTitle from '../../../hooks/useDocumentTitle'
import {Policy} from '../../../rest/branches'
import {getHrefWithQueryParams} from '../../../routes'
import type {Branch} from '../../../services/rest'
import {restApi} from '../../../services/rest'
import {getProjectBuildTypeFilter, stringifyId} from '../../../types'
import {BS} from '../../../types/BS_types'
import {stringifyBranch} from '../../../utils/branchNames'
import {emptyArray} from '../../../utils/empty'
import {subscribeOnProjectEvents} from '../../../utils/subscriber'
import {TEST_MUTE_UPDATED, TEST_RESPONSIBILITY_CHANGED} from '../../../utils/subscriptionEvents'
import CopyIconButton from '../../common/CopyIconButton/CopyIconButton'
import Loader from '../../common/Loader/Loader'
import OverviewTab from '../../common/OverviewTab/OverviewTab'
import tabStyles from '../../common/OverviewTab/OverviewTab.module.css'
import PageTitle from '../../common/PageTitle/PageTitle'
import Placeholder from '../../common/Placeholder/Placeholder'
import InvestigationHistory from '../../packages/InvestigationHistory/InvestigationHistoryList/InvestigationHistoryList'
import InvestigationMuteButtons from '../../packages/Tests/InvestigationMuteButtons/InvestigationMuteButtons'
import {getTestOccurenceArg} from '../../packages/Tests/Tests.rest'
import {getTestOccurrence} from '../../packages/Tests/Tests.selectors'
import {trimAndRemoveColon} from '../../packages/Tests/Tests.utils'

import TestOverviewTab from './OverviewTab/OverviewTab'
import ProjectsSelect from './ProjectsSelect/ProjectsSelect'
import {tabs, TestPageTabNamesEnum} from './TestHistoryPage.tabs'
import type {Props, TestTab} from './TestHistoryPage.types'

import styles from './TestHistoryPage.module.css'

function TestHistoryPage({
  testId,
  buildTypeId,
  projectId,
  pipelineId,
  projectInternalId,
  branch,
  projectName,
  buildTypeName,
  currentTab,
  branchesQueryRef,
}: Props) {
  const project = pipelineId
    ? `pipeline:${pipelineId}`
    : `affectedProject:${stringifyId(projectId)}`
  const locator = `test:(id:${stringifyId(testId)}),${project},includePersonal:true`
  const navigate = useNavigate()
  const location = useLocation()

  const {refetch, testOccurrenceId, isReady, error} =
    restApi.endpoints.getTestOccurrenceNormalized.useQuery(
      getTestOccurenceArg(locator, {
        withMuteInfo: true,
        withInvestigationInfo: true,
      }),
      {
        selectFromResult: ({data, error}) => ({
          testOccurrenceId: data?.result[0],
          isReady: data != null,
          error,
        }),
      },
    )
  const testName = useAppSelector(state => getTestOccurrence(state, testOccurrenceId)?.name)
  const testClass = useAppSelector(
    state => getTestOccurrence(state, testOccurrenceId)?.test?.parsedTestName?.testClass,
  )
  const testNameWithParameters = useAppSelector(
    state =>
      getTestOccurrence(state, testOccurrenceId)?.test?.parsedTestName?.testNameWithParameters,
  )
  const testSuite = useAppSelector(
    state => getTestOccurrence(state, testOccurrenceId)?.test?.parsedTestName?.testSuite,
  )
  const testPackage = useAppSelector(
    state => getTestOccurrence(state, testOccurrenceId)?.test?.parsedTestName?.testPackage,
  )

  const fullTestName =
    [testPackage, testClass, testNameWithParameters].filter(Boolean).join('.') || testName

  const entityName = projectName ?? buildTypeName
  useDocumentTitle(
    fullTestName != null && entityName != null
      ? `${entityName} > Test history of ${fullTestName} — TeamCity`
      : error
        ? `${entityName} > Test history — TeamCity`
        : 'TeamCity Loading...',
  )

  const testOccurrenceIds = useMemo(
    () => (testOccurrenceId != null ? [testOccurrenceId] : emptyArray),
    [testOccurrenceId],
  )
  const onSelectBranch = useCallback(
    (selected: Branch | null | undefined, replace?: boolean) => {
      const selectedBranch = stringifyBranch(selected)

      if (projectId != null && BS?.Branch) {
        BS.Branch.saveBranch(projectId, selectedBranch)
      }

      navigate(
        getHrefWithQueryParams(location, null, oldParams => ({
          ...oldParams,
          branch: selectedBranch,
          page: null,
        })),
        {replace, preventScrollReset: true},
      )
    },
    [navigate, location, projectId],
  )

  const getTabLink = useCallback(
    (tabId: string) =>
      getHrefWithQueryParams(location, null, params => ({...params, testTab: stringifyId(tabId)})),
    [location],
  )

  const onSelectTab = useCallback(
    (tabId: string) => navigate(getTabLink(tabId)),
    [navigate, getTabLink],
  )

  useEffect(
    () =>
      projectInternalId != null
        ? subscribeOnProjectEvents(
            projectInternalId,
            [TEST_RESPONSIBILITY_CHANGED, TEST_MUTE_UPDATED],
            refetch,
          )
        : undefined,
    [projectInternalId, refetch],
  )

  const getTabsComponents = useCallback(
    (id: string) => {
      switch (id) {
        case TestPageTabNamesEnum.OVERVIEW:
          return testOccurrenceId != null ? (
            <TestOverviewTab
              key={`${stringifyId(projectId)}_${stringifyId(buildTypeId)}_${stringifyBranch(
                branch,
              )}`}
              testOccurrenceId={testOccurrenceId}
              testId={testId}
              projectId={projectId}
              buildTypeId={buildTypeId}
            />
          ) : null

        case TestPageTabNamesEnum.INVESTIGATION_HISTORY:
          return (
            <InvestigationHistory
              projectInternalId={projectInternalId}
              locator={`projectId=${stringifyId(projectId)}&testNameId=${stringifyId(testId)}`}
            />
          )

        default:
          return null
      }
    },
    [testOccurrenceId, testId, projectId, buildTypeId, projectInternalId, branch],
  )
  const renderTab = useCallback(
    (tab: TestTab) => {
      const tabId = tab.id
      const tabPage = getTabsComponents(tabId)
      return (
        <OverviewTab
          key={stringifyId(tabId)}
          id={stringifyId(tabId)}
          title={tab.title}
          href={getTabLink(tabId)}
        >
          {tabPage}
        </OverviewTab>
      )
    },
    [getTabLink, getTabsComponents],
  )
  const renderHeading = useMemo(() => {
    const formatedTestSuite = testPackage ? testSuite : trimAndRemoveColon(testSuite ?? '')

    const headingName =
      [testClass, testNameWithParameters].filter(Boolean).join('.') || testName || ''
    const subheadingName = [formatedTestSuite, testPackage].filter(Boolean).join('.') || ''

    return (
      <PageTitle className={styles.heading}>
        <span className={styles.headingTestName}>{`Test\u00a0History:\u00a0${headingName}`}</span>
        <CopyIconButton
          wrapperClassName={styles.copyTestNameIconWrapper}
          iconClassName={styles.copyTestNameIcon}
          text={fullTestName}
        />
        {subheadingName !== '' && <div className={styles.subHeading}>{subheadingName}</div>}
      </PageTitle>
    )
  }, [testClass, testName, testNameWithParameters, fullTestName, testPackage, testSuite])

  if ((error as FetchBaseQueryError)?.status === HTTPCodesEnum.NOT_FOUND) {
    return (
      <div className={styles.header}>
        <PageTitle className={styles.heading}>
          <span className={styles.headingTestName}>{`Test\u00a0History`}</span>
        </PageTitle>
        <Placeholder message={'There is no test history found.'} />
      </div>
    )
  }

  if (!isReady) {
    return <Loader />
  }

  if (
    !window.GLOBAL_ERROR_PAGE_DISABLED &&
    ((projectId == null && pipelineId == null) || testOccurrenceId == null)
  ) {
    const entity = projectId != null ? 'project' : 'pipeline'
    const id = projectId != null ? projectId : pipelineId
    const errorMessage =
      testOccurrenceId == null && (projectId != null || pipelineId != null)
        ? `Test with\u00a0id '${stringifyId(
            testId,
          )}' does\u00a0not\u00a0exist in\u00a0${entity}\u00a0with\u00a0id '${stringifyId(id)}'`
        : '404. Oops... wrong link'
    throw new HTTPError(errorMessage, HTTPCodesEnum.NOT_FOUND)
  }

  return testOccurrenceId != null ? (
    <>
      <div className={styles.header}>
        {renderHeading}
        <ProjectsSelect buildTypeId={buildTypeId} projectId={projectId} testId={testId} />
        <div>
          <Suspense>
            <BranchFilter
              className={styles.branchFilter}
              projectOrBuildTypeNode={getProjectBuildTypeFilter({
                projectId,
                buildTypeId,
              })}
              onSelect={onSelectBranch}
              policy={Policy.HISTORY_BRANCHES}
              branchesQueryRef={branchesQueryRef}
            />
          </Suspense>
          <Suspense>
            <InvestigationMuteButtons
              className={styles.investigationMuteButtons}
              projectId={projectId}
              testOccurrencesIds={testOccurrenceIds}
              onAction={refetch}
            />
          </Suspense>
        </div>
      </div>
      <Tabs
        key={`${stringifyId(testId)}`}
        selected={currentTab}
        onSelect={onSelectTab}
        className={tabStyles.tabs}
      >
        {tabs.map(tab => renderTab(tab))}
      </Tabs>
    </>
  ) : null
}

export default memo(TestHistoryPage)
